import { readFile, writeFile } from "node:fs/promises";
import { answerInstructions } from "../src/course-maker/ui/assistant/answer-library.tsx";

const target = new URL(
  "../../backend/src/app/courses/adapters/ai/answer_prompt.md",
  import.meta.url,
);
const content =
  "<!-- Generated by npm run generate:answer-prompt in frontend. Do not edit by hand. -->\n" +
  answerInstructions;
if (process.argv.includes("--check")) {
  if ((await readFile(target, "utf8")) !== content)
    throw new Error(
      "Agent answer prompt is stale. Run npm run generate:answer-prompt.",
    );
} else await writeFile(target, content);
